SELECT COUNT(*) FROM knowledge_item i JOIN knowledge_version v
  ON v.owner_id = i.owner_id AND v.item_id = i.id
WHERE i.owner_id = #{owner} AND i.id = #{id} AND v.id = #{version}

SELECT COUNT(*) FROM question q JOIN question_version v
  ON v.owner_id = q.owner_id AND v.question_id = q.id
WHERE q.owner_id = #{owner} AND q.id = #{id} AND v.id = #{version}
